func (m Model) status() sharedcomponents.Status {
	var st sharedcomponents.Status
	if p := jobs.Summarize(m.visibleRuns(), nil, 0); p.Running > 0 {
		st.Text = sharedcomponents.Plural(p.Running, "job", "jobs") + " running"
