func TestANonLoadingStatusHasNoSpinner(t *testing.T) {
	var f FooterMessage
	f.SetSpinnerFrame("⠹")

	line := stripANSI(f.View(60, Status{Text: "Pruning containers…"}))
	if strings.Contains(line, "⠹") {
		t.Errorf("a status that did not ask for a spinner got one:\n%q", line)
	}
}

