	var f FooterMessage
	f.SetSpinnerFrame("⠹")
	f.Warn("Scan already in progress")

	line := stripANSI(f.View(60, Status{Text: "Loading images…", Spinner: true}))
	if strings.Contains(line, "⠹") {
		t.Errorf("a timed message rendered the spinner:\n%q", line)
	}
}

